interface BadgeProps { children: ReactNode; tone?: 'sky' | 'emerald' | 'amber' | 'rose' | 'slate' }
function Badge({ children, tone = 'slate' }: BadgeProps) {
  const colors = { sky: 'border-sky-500/30 bg-sky-500/10 text-sky-400', emerald: 'border-emerald-500/30 bg-emerald-500/10 text-emerald-400', amber: 'border-amber-500/30 bg-amber-500/10 text-amber-400', rose: 'border-rose-500/30 bg-rose-500/10 text-rose-400', slate: 'border-slate-700 bg-slate-800 text-slate-300' };
  return <span className={`inline-flex items-center gap-1 rounded-full border px-2.5 py-1 text-xs ${colors[tone]}`}>{children}</span>;
}
interface ModalProps { title: string; children: ReactNode; onClose: () => void; wide?: boolean }
function Modal({ title, children, onClose, wide = false }: ModalProps) {
  useEffect(() => { const handle = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); }; window.addEventListener('keydown', handle); return () => window.removeEventListener('keydown', handle); }, [onClose]);
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/85 p-4 backdrop-blur-sm" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }} role="presentation">
    <section role="dialog" aria-modal="true" aria-label={title} className={`${panel} max-h-[90vh] w-full ${wide ? 'max-w-5xl' : 'max-w-2xl'} overflow-y-auto shadow-2xl`}>
      <header className="sticky top-0 z-10 flex items-center justify-between border-b border-slate-800 bg-slate-900 px-6 py-4"><h2 className="text-lg font-semibold text-slate-50">{title}</h2><button type="button" aria-label="Закрыть" onClick={onClose} className="text-slate-400 hover:text-white"><X size={20}/></button></header>
      <div className="p-6">{children}</div>
    </section>
  </div>;
}
